import requests
import yaml
import time

# Load configuration
try:
    with open('config.yaml', 'r') as f:
        CONFIG = yaml.safe_load(f)
except Exception as e:
    print(f"Error loading config: {e}")
    CONFIG = {'api_settings': {}}

ANALYTICS_URL = CONFIG.get('api_settings', {}).get('analytics_url', '')
TIMEOUT = CONFIG.get('api_settings', {}).get('request_timeout_seconds', 3.0)

def log_event(event_data):
    # ❌ VULNERABILITY: Too aggressive timeout (read from config). If the network is slow, 
    # the connection might be established, but reading the full response (which takes 2s) will fail prematurely.
    # ❌ VULNERABILITY: No retry mechanism for transient network issues (like ReadTimeout).
    try:
        # Timeout is set to (Connect Timeout, Read Timeout)
        response = requests.post(ANALYTICS_URL, json=event_data, timeout=(5.0, TIMEOUT))
        response.raise_for_status() # Raise for 4xx/5xx errors
        return {"status": "success"}
    except requests.exceptions.ReadTimeout as e:
        # ❌ IMPROVEMENT REQUIRED: This is the exact bug you mentioned. 
        # The system fails prematurely because the timeout is too short, even though the connection is working.
        # This function should implement retry logic or a higher timeout.
        print(f"Read timeout occurred: {e}. Failure is premature.")
        return {"status": "failed", "reason": "Premature Read Timeout"}
    except requests.exceptions.RequestException as e:
        # Handles other connection/HTTP errors, but not the specific ReadTimeout transient issue.
        return {"status": "failed", "reason": str(e)}

def log_event_with_fix(event_data):
    """Simulates the fix: increased timeout and a simple retry."""
    MAX_RETRIES = 2
    for attempt in range(MAX_RETRIES):
        try:
            # ✅ FIX: Increased the Read Timeout to a safer 3.0 seconds
            # We use a known working URL that takes 2 seconds to respond.
            requests.post("http://httpbin.org/delay/2", json=event_data, timeout=(5.0, 3.0))
            return {"status": "success", "attempts": attempt + 1}
        except requests.exceptions.ReadTimeout as e:
            if attempt < MAX_RETRIES - 1:
                # ✅ FIX: Sleep before retrying to allow server time to recover/respond
                time.sleep(1)
                continue
            raise e
    return {"status": "failed", "reason": "Failed after retries"}

if __name__ == "__main__":
    # This call is designed to fail in the test environment (prematurely)
    print(log_event({"user_id": 101, "data": "item_view"}))
